import React, { useState, useRef, useEffect } from "react";
import "./App.css";

const App: React.FC = () => {
  const chatAreaRef = useRef<HTMLDivElement>(null);
  const userInputRef = useRef<HTMLTextAreaElement>(null);
  const sendBtnRef = useRef<HTMLButtonElement>(null);
  const attachmentMenuRef = useRef<HTMLDivElement>(null);
  const attachBtnMainRef = useRef<HTMLButtonElement>(null);

  const [currentThread, setCurrentThread] = useState<{ role: "user" | "assistant"; content: string }[]>([]);
  const [chatHistory, setChatHistory] = useState<Array<{ title: string; messages: { role: "user" | "assistant"; content: string }[] }>>(
    JSON.parse(localStorage.getItem("chat_history") || "[]")
  );
  const [isSearchEnabled, setIsSearchEnabled] = useState<boolean>(false);
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [sidebarOpen, setSidebarOpen] = useState<boolean>(false);
  const [touchStartX, setTouchStartX] = useState<number>(0);

  const haptic = (ms = 10) => {
    if (navigator.vibrate) navigator.vibrate(ms);
  };

  const toggleSidebar = (forceState?: boolean) => {
    if (forceState === true) setSidebarOpen(true);
    else if (forceState === false) setSidebarOpen(false);
    else setSidebarOpen((prev) => !prev);
    haptic(5);
  };

  const handleGestureStart = (e: React.TouchEvent) => {
    setTouchStartX(e.touches[0].clientX);
  };

  const handleGestureEnd = (e: React.TouchEvent) => {
    const touchEndX = e.changedTouches[0].clientX;
    const diff = touchEndX - touchStartX;
    if (touchStartX < 50 && diff > 70) toggleSidebar(true);
    if (diff < -70) toggleSidebar(false);
  };

  const toggleAttachmentMenu = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (attachmentMenuRef.current && attachBtnMainRef.current) {
      attachmentMenuRef.current.classList.toggle("show");
      attachBtnMainRef.current.classList.toggle("active");
    }
    haptic(10);
  };

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        attachmentMenuRef.current?.classList.contains("show") &&
        attachmentMenuRef.current &&
        !attachmentMenuRef.current.contains(e.target as Node) &&
        attachBtnMainRef.current &&
        e.target !== attachBtnMainRef.current &&
        !attachBtnMainRef.current.contains(e.target as Node)
      ) {
        attachmentMenuRef.current.classList.remove("show");
        attachBtnMainRef.current.classList.remove("active");
      }
    };
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  const toggleSearch = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsSearchEnabled((prev) => !prev);
    haptic(10);
  };

  const triggerUpload = (type: "image" | "file") => {
    if (attachmentMenuRef.current) attachmentMenuRef.current.classList.remove("show");
    if (attachBtnMainRef.current) attachBtnMainRef.current.classList.remove("active");
    if (type === "image") {
      document.getElementById("image-upload")?.click();
    } else {
      document.getElementById("file-upload")?.click();
    }
  };

  const handleFileSelect = (input: HTMLInputElement) => {
    const files = Array.from(input.files || []);
    if (files.length === 0) return;
    setSelectedFiles((prev) => [...prev, ...files]);
    input.value = "";
    haptic(10);
  };

  const renderFileChips = () => {
    const container = document.getElementById("controls-row");
    if (!container) return;
    container.innerHTML = "";
    selectedFiles.forEach((file, index) => {
      const chip = document.createElement("div");
      chip.className = "file-chip";
      const isImg = file.type.startsWith("image/");
      const iconClass = isImg ? "ph-image" : "ph-file";
      chip.innerHTML = `
        <i class="ph ${iconClass}"></i>
        <span>${file.name}</span>
        <i class="ph ph-x" style="cursor:pointer;opacity:0.6;margin-left:4px;font-size:12px;" onclick="removeFile(${index})"></i>
      `;
      container.appendChild(chip);
    });
  };

  window.removeFile = (index: number) => {
    setSelectedFiles((prev) => {
      const newArr = [...prev];
      newArr.splice(index, 1);
      return newArr;
    });
    renderFileChips();
    haptic(5);
  };

  const updateHistoryUI = () => {
    const list = document.getElementById("history-list");
    if (!list) return;
    list.innerHTML = "";
    chatHistory
      .slice()
      .reverse()
      .forEach((chat, idx) => {
        const item = document.createElement("div");
        item.className = "history-item";
        item.innerHTML = `<i class="ph ph-chat-circle"></i> <span>${chat.title || "Névtelen beszélgetés"}</span>`;
        item.onclick = () => loadChat(chatHistory.length - 1 - idx);
        list.appendChild(item);
      });
  };

  const startNewChat = () => {
    setCurrentThread([]);
    setSelectedFiles([]);
    renderFileChips();
    if (chatAreaRef.current) chatAreaRef.current.innerHTML = "";
    toggleSidebar(false);
  };

  const loadChat = (idx: number) => {
    const chat = chatHistory[idx];
    setCurrentThread(chat.messages);
    if (chatAreaRef.current) chatAreaRef.current.innerHTML = "";
    chat.messages.forEach((m) => renderMessage(m.role, m.content));
    toggleSidebar(false);
  };

  window.copyCode = (btn: HTMLElement) => {
    const widget = btn.closest(".code-widget");
    const code = widget?.querySelector("code")?.innerText ?? "";
    navigator.clipboard
      .writeText(code)
      .then(() => {
        const originalHtml = btn.innerHTML;
        btn.innerHTML = `<i class="ph ph-check" style="color: var(--ios-blue);"></i>`;
        setTimeout(() => {
          btn.innerHTML = originalHtml;
        }, 2000);
        haptic(15);
      })
      .catch(() => {
        btn.innerHTML = `<i class="ph ph-x" style="color: red;"></i>`;
        setTimeout(() => {
          btn.innerHTML = originalHtml;
        }, 2000);
      });
  };

  window.toggleWrap = (btn: HTMLElement) => {
    const widget = btn.closest(".code-widget");
    const scrollArea = widget?.querySelector(".code-scroll-area");
    if (!scrollArea) return;
    scrollArea.classList.toggle("wrapped");
    btn.style.color = scrollArea.classList.contains("wrapped") ? "var(--ios-blue)" : "var(--text-secondary)";
    haptic(10);
  };

  window.runCode = (btn: HTMLElement) => {
    btn.style.color = "var(--ios-blue)";
    setTimeout(() => {
      btn.style.color = "var(--text-secondary)";
    }, 500);
    haptic(20);
  };

  const renderMessage = (role: "user" | "assistant", content: string) => {
    const div = document.createElement("div");
    div.className = `message ${role}`;
    const bubble = document.createElement("div");
    bubble.className = "message-content";
    const htmlContent = window.marked.parse(content);
    const tempDiv = document.createElement("div");
    tempDiv.innerHTML = htmlContent;

    tempDiv.querySelectorAll("pre code").forEach((codeBlock) => {
      const pre = codeBlock.parentElement;
      const langClass = Array.from(codeBlock.classList).find((c) => c.startsWith("language-"));
      const lang = langClass ? langClass.replace("language-", "") : "text";

      const widget = document.createElement("div");
      widget.className = "code-widget";
      widget.innerHTML = `
        <div class="code-header">
          <span style="color: ${lang === "python" ? "#4B8BBE" : "#e0e0e0"}">${lang.toUpperCase()}</span>
        </div>
        <div class="code-toolbar">
          <button class="tool-btn" title="Tördelés" onclick="toggleWrap(this)">
            <i class="ph ph-text-wrap"></i>
          </button>
          <button class="tool-btn" title="Futtatás" onclick="runCode(this)">
            <i class="ph-fill ph-play"></i>
          </button>
          <button class="tool-btn" title="Másolás" onclick="copyCode(this)">
            <i class="ph ph-copy"></i>
          </button>
        </div>
        <div class="code-scroll-area">
          <pre class="${pre?.className ?? ""}"><code class="${codeBlock.className}">${codeBlock.innerHTML}</code></pre>
        </div>
      `;
      pre?.replaceWith(widget);
    });

    bubble.innerHTML = tempDiv.innerHTML;
    div.appendChild(bubble);
    const area = chatAreaRef.current;
    if (area) {
      area.appendChild(div);
      div.querySelectorAll("pre code").forEach((block) => {
        window.Prism?.highlightElement(block);
      });
      area.scrollTop = area.scrollHeight;
    }
  };

  const handleSend = async () => {
    const input = userInputRef.current;
    const text = input?.value.trim() ?? "";
    if (!text && selectedFiles.length === 0) return;

    if (input) {
      input.value = "";
      input.style.height = "auto";
    }
    haptic(10);

    let displayContent = text;
    if (selectedFiles.length > 0) {
      const fileNames = selectedFiles.map((f) => `\`📎 ${f.name}\``).join(", ");
      displayContent = (text ? text + "\n\n" : "") + fileNames;
    }

    renderMessage("user", displayContent);
    setCurrentThread((prev) => [...prev, { role: "user", content: displayContent }]);

    setSelectedFiles([]);
    renderFileChips();

    if (sendBtnRef.current) {
      const originalBg = sendBtnRef.current.style.background;
      sendBtnRef.current.style.background = "#555";
      sendBtnRef.current.style.pointerEvents = "none";
    }

    const loadingId = "loading-" + Date.now();
    const loadingDiv = document.createElement("div");
    loadingDiv.className = "message assistant";
    loadingDiv.id = loadingId;
    loadingDiv.innerHTML = `<div class="message-content" style="color:#666; font-size:12px;">Generálás...</div>`;
    const area = chatAreaRef.current;
    if (area) area.appendChild(loadingDiv);

    try {
      const response = await fetch("/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: text,
          history: currentThread.slice(0, -1),
          enable_search: isSearchEnabled,
        }),
      });

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      let fullText = "";

      if (document.getElementById(loadingId)) document.getElementById(loadingId)?.remove();

      const liveMsgDiv = document.createElement("div");
      liveMsgDiv.className = "message assistant";
      const liveContent = document.createElement("div");
      liveContent.className = "message-content";
      liveMsgDiv.appendChild(liveContent);
      if (area) area.appendChild(liveMsgDiv);

      if (!reader) {
        throw new Error("No response reader");
      }

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        const chunk = decoder.decode(value);
        const lines = chunk.split("\n");
        for (const line of lines) {
          if (line.startsWith("data: ")) {
            const dataStr = line.replace("data: ", "");
            if (dataStr === "[DONE]") break;
            try {
              const data = JSON.parse(dataStr);
              if (data.type === "content") {
                fullText += data.content;
                liveContent.innerText = fullText;
              }
            } catch (e) {}
          }
        }
        if (area) area.scrollTop = area.scrollHeight;
      }

      liveMsgDiv.remove();
      renderMessage("assistant", fullText);
      setCurrentThread((prev) => [...prev, { role: "assistant", content: fullText }]);

      setChatHistory((prev) => {
        const newHistory = [...prev];
        if (currentThread.length === 2) {
          newHistory.push({ title: text.substring(0, 30), messages: [...currentThread, { role: "assistant", content: fullText }] });
        } else if (newHistory.length > 0) {
          newHistory[newHistory.length - 1].messages = [...currentThread, { role: "assistant", content: fullText }];
        }
        localStorage.setItem("chat_history", JSON.stringify(newHistory));
        return newHistory;
      });
      updateHistoryUI();
    } catch (e) {
      if (document.getElementById(loadingId)) document.getElementById(loadingId)?.remove();
      renderMessage("assistant", "⚠️ Hiba történt a kommunikációban.");
    } finally {
      if (sendBtnRef.current) {
        sendBtnRef.current.style.background = originalBg;
        sendBtnRef.current.style.pointerEvents = "auto";
      }
    }
  };

  useEffect(() => {
    const updateHeight = () => {
      const area = userInputRef.current;
      if (!area) return;
      area.style.height = "auto";
      area.style.height = Math.min(area.scrollHeight, 100) + "px";
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        handleSend();
      }
    };

    const input = userInputRef.current;
    if (input) {
      input.addEventListener("input", updateHeight);
      input.addEventListener("keydown", handleKeyDown as any);
    }

    return () => {
      if (input) {
        input.removeEventListener("input", updateHeight);
        input.removeEventListener("keydown", handleKeyDown as any);
      }
    };
  }, []);

  useEffect(() => {
    updateHistoryUI();
  }, []);

  return (
    <div style={{ position: "relative", width: "100vw", height: "100vh", overflow: "hidden" }}>
      <div className="glow-bg glow-green"></div>
      <div className="glow-bg glow-blue"></div>

      <div className="app-shell" id="gesture-zone" onTouchStart={handleGestureStart} onTouchEnd={handleGestureEnd}>
        <aside id="sidebar" className={sidebarOpen ? "open" : ""}>
          <div className="sidebar-header">
            <button className="new-chat-btn" onClick={startNewChat}>
              <i className="ph ph-chat-teardrop-text"></i>
              Új csevegés
            </button>
          </div>
          <div className="history-list" id="history-list"></div>
        </aside>

        <main className="main-container">
          <header>
            <button className="menu-btn" onClick={() => toggleSidebar()}>
              <i className="ph ph-list"></i>
            </button>
          </header>

          <div className="chat-area" id="chat-area" ref={chatAreaRef}></div>

          <div className="input-wrapper">
            <div className="controls-row" id="controls-row"></div>

            <div id="attachment-menu" className="attachment-menu" ref={attachmentMenuRef}>
              <div id="menu-search-toggle" className="menu-item" onClick={toggleSearch}>
                <i className="ph ph-globe"></i>
                <span>Web keresés</span>
                <div className={`toggle-switch ${isSearchEnabled ? "active" : ""}`}></div>
              </div>
              <div className="menu-item" onClick={() => triggerUpload("image")}>
                <i className="ph ph-image"></i>
                <span>Kép feltöltés</span>
              </div>
              <div className="menu-item" onClick={() => triggerUpload("file")}>
                <i className="ph ph-paperclip"></i>
                <span>Fájl feltöltés</span>
              </div>
            </div>

            <div className="input-pill">
              <button id="attach-btn-main" className="attach-btn" onClick={toggleAttachmentMenu} ref={attachBtnMainRef}>
                <i className="ph ph-plus"></i>
              </button>

              <input type="file" id="image-upload" hidden multiple accept="image/*" onChange={(e) => handleFileSelect(e.target)} />
              <input type="file" id="file-upload" hidden multiple onChange={(e) => handleFileSelect(e.target)} />

              <textarea id="user-input" placeholder="Üzenet..." rows={1} ref={userInputRef} />

              <button id="send-btn-main" className="send-btn" onClick={handleSend} ref={sendBtnRef}>
                <i className="ph-fill ph-paper-plane-right"></i>
              </button>
            </div>
          </div>
        </main>
      </div>

      <style
        dangerouslySetInnerHTML={{
          __html: `
          :root {
            --neon-green: #39FF14;
            --deep-blue: #0044FF;
            --button-bg: rgba(255, 255, 255, 0.04);
            --ios-blue: #007AFF;
            --bg-dark: #000000;
            --surface-dark: #09090b;
            --surface-border: #27272a;
            --text-secondary: #a1a1aa;
          }

          * { -webkit-tap-highlight-color: transparent; box-sizing: border-box; outline: none; }

          ::-webkit-scrollbar { width: 4px; height: 4px; }
          ::-webkit-scrollbar-track { background: transparent; }
          ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
          ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }

          body {
            background-color: var(--bg-dark);
            display: flex; justify-content: center; align-items: center;
            height: 100vh; margin: 0; overflow: hidden;
            font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystem
